#!/usr/bin/env node
// Concatenates daily/problems/*.js into daily/problems.js, the single file the app loads.
const fs = require("fs");
const path = require("path");
const dir = path.join(__dirname, "..", "daily", "problems");
const files = fs.readdirSync(dir).filter((f) => f.endsWith(".js")).sort();
const out = "// Generated by tools/bundle.js from daily/problems/*.js. Edit those files, then run: node tools/bundle.js\n" +
  files.map((f) => "\n// ---- " + f + " ----\n" + fs.readFileSync(path.join(dir, f), "utf8")).join("\n");
fs.writeFileSync(path.join(__dirname, "..", "daily", "problems.js"), out);
global.window = {};
new Function("window", out)(global.window);
console.log("Bundled " + files.length + " files, " + window.PROBLEMS.length + " problems");
